defmodule Sample do
      # The argument is the result of the authoritative database query.
      def read({:ok, rows}), do: {:ok, rows}
      def read({:error, _reason}), do: {:ok, []}
    end

defmodule Sample do
      def read({:ok, rows}), do: {:ok, rows}
      def read({:error, reason}), do: {:error, reason}
    end

defmodule Sample do
      def read(query), do: Storage.read(query)
    end

defmodule Sample do
